// Run tokens: readable claims plus an HMAC signature. Only someone who holds SIGNING_KEY can make one.
import { createHmac, timingSafeEqual } from "node:crypto";

export type RunClaims = { agent: string; jira: string; run: string; exp: number; epoch: number };

const SIGNING_KEY = process.env.SIGNING_KEY ?? "lab-only-signing-key";
const sign = (body: string) => createHmac("sha256", SIGNING_KEY).update(body).digest();

export const mintRunToken = (claims: RunClaims): string => {
  const body = Buffer.from(JSON.stringify(claims)).toString("base64url");
  return `${body}.${sign(body).toString("base64url")}`;
};

export const verifyRunToken = (header = ""): RunClaims => {
  const [body = "", sig = ""] = header.replace(/^Bearer /, "").split(".");
  const want = sign(body);
  const got = Buffer.from(sig, "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) throw new Error("bad signature");
  const claims = JSON.parse(Buffer.from(body, "base64url").toString()) as RunClaims;
  if (claims.exp < Date.now() / 1000) throw new Error("expired");
  return claims;
};

